select case when s.rating >= 3.7 then 'high' when s.rating >= 1.9 then 'mid' else 'low' end as rating_bucket, max(i.quantity) - min(i.quantity) as quantity_range, avg(i.quantity) as avg_quantity from inventory i left outer join products p on i.product_id = p.id join suppliers s on p.supplier_id = s.id where s.country = 'TH' group by case when s.rating >= 3.7 then 'high' when s.rating >= 1.9 then 'mid' else 'low' end order by rating_bucket, avg_quantity desc limit 1
